class Solution { public:
    int reachableNodes(int n,vector<vector<int>>& edges,vector<int>& restricted) {
        vector<vector<int>> adj(n);for(auto &e:edges){adj[e[0]].push_back(e[1]);adj[e[1]].push_back(e[0]);}
        vector<char> seen(n,0);for(int x:restricted)seen[x]=1;
        queue<int> q;q.push(0);seen[0]=1;int ans=0;
        while(!q.empty()){int u=q.front();q.pop();++ans;
            for(int v:adj[u])if(!seen[v]){seen[v]=1;q.push(v);}
        }
        return ans;
    }
};
